using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// --- 1. Strongly-typed retrieval: GetTypeInfo<T>() --------------------------
// Returns JsonTypeInfo<T> directly — no casting needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine(json);

// --- 2. Probe without throwing: TryGetTypeInfo --------------------------------
// Returns false instead of throwing if the type isn't resolvable.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? resolved))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {resolved!.Type.Name}");
}

// Now try a type that the resolver can't handle (a made-up open generic, for example).
// With no resolver at all, nothing is resolvable:
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (!empty.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("TryGetTypeInfo(Person) on resolver-less options: not available (no exception thrown)");
}

public record Person(string Name, int Age);

